"""Generate C6-only report and TeX from C6 summary JSON."""
import sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parent))
from wpc_c6 import *
from analyze_wpc_c6 import BASES,TRANSFER
from build_wpc_results import table,pct

def main():
    gate();s=read(OUT/'c6/summary.json')['data'];paired=read(OUT/'c6/paired-comparisons.json')['data'];tex=OUT/'c6/tex';tex.mkdir(exist_ok=False)
    selected=['stress:indentation','stress:duplicates','stress:short','controlled:replication','real','real:oss:targeted','external:human-AB','external:human-AB:non-Python-code','external:variable_test','external:block_test','external:method_test','external:suppression']
    tables=[];head=[]
    for name in selected:
        x=s['strata'][name];rows=[]
        for m in BASES+TRANSFER:
            v=x['methods'][m];rows.append([m,v['n'],pct(v['accuracy']),pct(v['missed']),pct(v['wrong_silent']),pct(v['lost']),pct(v['false_recheck']),v['execution_errors']])
        filename='table-c6-'+name.replace(':','-')+'.tex';table(tex/filename,['Method','N','Correct %','Miss %','Silent %','Lost %','False %','Errors'],rows);tables.append(filename)
        for matcher in MATCHERS:
            m=matcher+'+IG+AG';v=x['methods'][m];d=next(d for d in s['dominance'] if d['population']==name and d['method']==m)
            head.append(f"- {name}, {m}: correct {v['accuracy']['k']}/{v['n']}; missed {v['missed']['k']}/{v['missed']['n']}; wrong-silent {v['wrong_silent']['k']}/{v['wrong_silent']['n']}; lost {v['lost']['k']}/{v['lost']['n']}; false re-check {v['false_recheck']['k']}/{v['false_recheck']['n']}; errors {v['execution_errors']}. Descriptive safety dominance: {d['descriptive_safety_dominance']}; both safety CI upper limits nonpositive: {d['both_safety_upper_limits_nonpositive']}.")
    wins=[d for d in s['dominance'] if d['descriptive_safety_dominance']]
    supported=[d for d in wins if d['both_safety_upper_limits_nonpositive']]
    real=s['strata']['real']['methods'];gt=real['gumtree+IG+AG'];base=real[BASES[0]];track=real['tracker+IG+AG'];hy=real['hybrid+IG+AG']
    human=s['strata']['external:human-AB:non-Python-code']['methods'];cm=human['codemapper+IG+AG'];hb=human[BASES[0]]
    lines=['# WP C6 results — separate retrospective extension','',
      'C1–C5 remain complete and unchanged in `V11-WPC-RESULTS.md`. This analysis was registered after seeing those results; none of its populations is described as newly held out.','',
      '## Top findings','',
      f"1. On all real histories, GumTree+IG+AG changes missed re-checks from {base['missed']['k']} to {gt['missed']['k']} and wrong-silent placements from {base['wrong_silent']['k']} to {gt['wrong_silent']['k']}; lost falls from {base['lost']['k']} to {gt['lost']['k']}, with {gt['execution_errors']} execution errors. False re-checks rise from {base['false_recheck']['k']} to {gt['false_recheck']['k']}. The AST-construction caveat still applies.",
      f"2. On {cm['n']} human A/B non-Python cases, CodeMapper+IG+AG changes missed re-checks from {hb['missed']['k']} to {cm['missed']['k']}, wrong-silent from {hb['wrong_silent']['k']} to {cm['wrong_silent']['k']}, and lost from {hb['lost']['k']} to {cm['lost']['k']}; false re-checks change from {hb['false_recheck']['k']} to {cm['false_recheck']['k']}. Mapping accuracy remains {cm['accuracy']['k']}/{cm['n']}; only labels/re-check decisions change.",
      f"3. The hybrid is a trade-off: versus strict tracker+IG+AG on histories, lost changes from {track['lost']['k']} to {hy['lost']['k']}, while missed changes from {track['missed']['k']} to {hy['missed']['k']} and wrong-silent from {track['wrong_silent']['k']} to {hy['wrong_silent']['k']}. It does not dominate that tracker on every safety dimension.",'',
      f"C6 evaluated {s['n']} observations. Across the predefined headline populations and fixed layer combinations, {len(wins)} comparisons satisfy the registered descriptive safety-dominance rule and {len(supported)} also have both nominal cluster-CI upper safety limits at or below zero. These are overlapping comparisons, not independent discoveries. The full false re-check, placement, error and lost costs remain visible. There is no semantic-identity or workload-benefit certificate.",'']
    for name in ('real','real:oss:targeted','external:human-AB:non-Python-code'):
        x=s['strata'][name];base=x['methods'][BASES[0]]
        lines.append(f"{name}, deployed: correct {base['accuracy']['k']}/{base['n']}; missed {base['missed']['k']}/{base['missed']['n']}; wrong-silent {base['wrong_silent']['k']}/{base['wrong_silent']['n']}; lost {base['lost']['k']}/{base['lost']['n']}.")
        for matcher in MATCHERS:
            m=matcher+'+IG+AG';v=x['methods'][m];d=next(d for d in s['dominance'] if d['population']==name and d['method']==m)
            lines.append(f"- {m}: correct {v['accuracy']['k']}/{v['n']}; missed {v['missed']['k']}/{v['missed']['n']}; wrong-silent {v['wrong_silent']['k']}/{v['wrong_silent']['n']}; lost {v['lost']['k']}/{v['lost']['n']}; false re-check {v['false_recheck']['k']}/{v['false_recheck']['n']}. Descriptive dominance: {d['descriptive_safety_dominance']}; both safety upper limits <=0: {d['both_safety_upper_limits_nonpositive']}.")
        lines.append('')
    lines+=['## Protocol and interpretation','',
      'The original C1–C5 bytes still hash to b5af90afd37561f29c76ad87a7585d33e31adfe7d89ad7de57bd8ce3e639d2ac. The appended amendment and timestamp are independently pinned in `c6-protocol-freeze.json`. Every batch and safety-family call verifies the original segment, amendment, combined protocol and frozen B1 code/helper hashes. No frozen B1 code changed. C1–C5 completion predates C6.','',
      'All four registered label layers (quotation, IG, AG, IG+AG) are evaluated over GumTree, CodeMapper, strict same-path contextual tracker and its registered cross-exact hybrid. IG/AG use the frozen post-selection predicates and never rerank a tool output. AG’s original candidate-selection preference is not transferable to an already fixed location; this boundary is stated in the amendment. Quote-only labels and guard labels are separately reported. Native character ranges remain those of the mapper; the label layer inspects their full-line workflow window. Tracker safety windows project original height, not a recovered end.','',
      'Native deployment (`deployed_native`) is separate from the frozen zero-switch family record (`t0.85-deployed`). On external data the former uses the C1–C5 separately executed native cascade; 39 Java block and 29 method cases completed natively while the B1 family timed out. Those failures remain in the frozen-family diagnostic. On constructed/history inputs, the frozen zero-switch exact deployed corner is reused, backed by the per-observation native reproduction gate. The reporting clarification is separately timestamped in `V11-WPC-C6-REPORTING-CLARIFICATION.md` and `c6/baseline-identity-clarification.json`; no raw mapping or protocol segment changed. None of the 68 differing cases hides a cross-file fallback, so hybrid outcomes are unchanged.','',
      'The hybrid falls back only after completed tracker no-match and only to frozen deployed cross_exact. Tracker failures do not trigger fallback. Renamed-path tracker results are excluded from strict original-path tracking unless the original path is present and a fresh same-path call succeeds. An absent original path yields completed no-match.','',
      'Dominance requires no worse missed or wrong-silent rate, one strictly better, and a lost-rate increase of at most one percentage point. Under the frozen metric definitions, execution failures are separate from lost, so this descriptive flag can coexist with additional execution failures and must not be read as operational dominance. Assess it jointly with errors, placement and false re-check costs. Nominal paired exact binomial tests and 10,000 fixed-seed cluster bootstraps compare each layer combination with deployed and both combined B1 thresholds. Source-file, commit-pair and repository/commit-pair clusters follow the amendment; no multiplicity-adjusted superiority is claimed.','',
      'Real-history truth shares Python-AST construction with GumTree and remains retrospective. Human A/B non-Python is separate from tool-derived suppression and Java-derived records. CodeMapper’s C1–C5 published-number gate failed; C6 does not repair or upgrade that gate. External cascade inputs remain paired-file restricted, and warm timings do not establish cold-start speed. No human disagreement adjudication or workload study is added.','',
      '## Full primary-layer counts','']+head+['','## Paths and governance','',
      '`evidence/v11-wpc/c6/summary.json` contains every suite/operator, real project/sampling group, external dataset and source-language result. `paired-comparisons.json` retains discordant counts, exact tests and bootstrap intervals. `c6/stress/` preserves newly executed stress mappings and fixtures; `c6/reuse/` stores separately relabelled C1–C5 outputs. `c6/tex/` contains generated fragments. Independent checks are in `c6/verification.json`; compilation/rendering and subsequent direct visual status are separately recorded in `tex-verification.json` and `visual-review.json`. `environment-verification.json` rechecks all pinned archive files and installed native CodeMapper source, and records actual NumPy/native-extension import paths. The initial environment check looked for the archived-results manifest in the tool directory; its failed log remains, and the corrected check uses the retained acquisition manifest.','',
      'The bounded CPU-worker restart preserved saved rows and all unfinished fixtures; resumed fixtures are checked against the exact old/new Git blob trees. The first taskkill returned descendant race/unsupported errors; subsequent independent process inspection confirmed that the former redirector and all six former worker PIDs were absent and only the resumed stress writer remained active. Initial test/import failures and interruption logs remain. This is an infrastructure concurrency change, not an algorithm/threshold change. No delegated agents, additional conversations, project commits/pushes, external messages, app/earlier evidence or AGENTS edits. AGENTS.md remains intentionally unchanged under the explicit scope restriction.']
    path=ROOT/'review/V11-WPC-C6-RESULTS.md';assert not path.exists();path.write_text('\n'.join(lines)+'\n',encoding='utf-8')
    write('c6/report-data.json',dict(tex_files={p.name:sha(p) for p in tex.glob('*.tex')},report_sha256=sha(path),descriptive_comparisons=len(wins),supported_comparisons=len(supported)),[OUT/'c6/summary.json',OUT/'c6/paired-comparisons.json',path])
    print('C6 report/TeX generated',len(tables),'tables',flush=True)
if __name__=='__main__':main()
